            }

            public init(from decoder: any Decoder) throws {
                let container = try decoder.container(keyedBy: CodingKeys.self)
                self.vaultID = container.contains(.vaultID)
                    ? try container.decode(Nullable<Int64>.self, forKey: .vaultID) : nil
                self.gatewayCredentialID = container.contains(.gatewayCredentialID)
                    ? try container.decode(Nullable<Int64>.self, forKey: .gatewayCredentialID) : nil
                self.limit = try container.decodeIfPresent(Int64.self, forKey: .limit)
                self.includeInactive = try container.decodeIfPresent(Bool.self, forKey: .includeInactive)
            }

            public func encode(to encoder: any Encoder) throws {
                var container = encoder.container(keyedBy: CodingKeys.self)
                try container.encodeIfPresent(self.vaultID, forKey: .vaultID)
                try container.encodeIfPresent(self.gatewayCredentialID, forKey: .gatewayCredentialID)
                try container.encodeIfPresent(self.limit, forKey: .limit)
                try container.encodeIfPresent(self.includeInactive, forKey: .includeInactive)
            }
        }

        public struct Response: Codable, Hashable, Sendable {
            public var policies: [WsModel.PriceBudgetPolicy]
            public var ledger: [WsModel.PriceBudgetLedgerEntry]
            public var trends: [WsModel.PriceBudgetTrendStats]
