extension Ws.Pricing.Notifications {
    /// Acknowledge a cost alert. Non super admins must send the alert's vault_id and be able to view it. A bare `id` is
    /// refused: send notification_id.
    public enum Ack: WsRequest {
        public static let command = WsCommand.pricingNotificationsAck

        public struct Payload: Codable, Hashable, Sendable {
            /// Minimum 1.
            public var notificationID: Int64
            /// Minimum 0. nil omits it, `.null` sends null.
            public var vaultID: Nullable<Int64>?

            public init(notificationID: Int64, vaultID: Nullable<Int64>? = nil) {
                self.notificationID = notificationID
                self.vaultID = vaultID
            }

            enum CodingKeys: String, CodingKey {
                case notificationID = "notification_id"
                case vaultID = "vault_id"
            }

            public init(from decoder: any Decoder) throws {
                let container = try decoder.container(keyedBy: CodingKeys.self)
                self.notificationID = try container.decode(Int64.self, forKey: .notificationID)
                self.vaultID = container.contains(.vaultID)
                    ? try container.decode(Nullable<Int64>.self, forKey: .vaultID) : nil
            }

            public func encode(to encoder: any Encoder) throws {
                var container = encoder.container(keyedBy: CodingKeys.self)
                try container.encode(self.notificationID, forKey: .notificationID)
                try container.encodeIfPresent(self.vaultID, forKey: .vaultID)
            }
        }

        public struct Response: Codable, Hashable, Sendable {
            public var notification: WsModel.PriceBudgetNotification

            public init(notification: WsModel.PriceBudgetNotification) {
                self.notification = notification
            }

            enum CodingKeys: String, CodingKey {
                case notification
            }
        }
    }
}

extension Ws.Pricing.Notifications {
    /// Cost alerts (operator notifications) the caller can see, newest first. summary always covers every OPEN alert in
    /// the same scope, whatever limit and include_acknowledged are.
